    `record` 는 팀장 세션이 최종 통합 검증 직후 한 번 부른다. `validate` 는 누구든
    (부모 Codex 포함) 그 기록이 이번 실행의 근거로 인정되는지 다시 확인할 때 쓴다 —
    LLM 을 부르지 않는 결정적 검사다.
    """
    state = _load(args)
    if state is None:
        return EXIT_USAGE

    if args.complete_cmd == "record":
        criteria: list[Any] = []
        try:
            if args.criteria_json:
                raw = json.loads(Path(args.criteria_json).read_text(encoding="utf-8"))
                if not isinstance(raw, list):
                    out("오류: --criteria-json 파일은 합격 기준 객체의 배열이어야 합니다.")
                    return EXIT_USAGE
                criteria.extend(raw)
            criteria.extend(_parse_criterion_spec(spec) for spec in (args.criterion or []))
            whole_task: dict[str, Any] = {}
            if args.whole_task_json:
                raw_whole = json.loads(Path(args.whole_task_json).read_text(encoding="utf-8"))
                if not isinstance(raw_whole, dict):
                    out("오류: --whole-task-json 파일은 객체여야 합니다.")
                    return EXIT_USAGE
                whole_task.update(raw_whole)
            if args.all_complete is not None:
                whole_task["all_requested_work_complete"] = args.all_complete == "yes"
            for key, values in (
                ("remaining_required", args.remaining),
                ("blockers", args.blocker),
                ("optional_next", args.optional_next),
            ):
                if values:
                    whole_task[key] = list(whole_task.get(key) or []) + list(values)

            record = completion_record.write_record(
                state,
                run_id=args.run_id,
                verdict=args.verdict,
                criteria=criteria,
                pending_owned_work=args.pending,
                whole_task=whole_task or None,
                verification={
                    "command": args.test_command,
                    "passed": args.tests_passed,
                    "failed": args.tests_failed,
                    "reran_only_failed": bool(args.reran_only_failed),
                },
                notes=args.note or "",
            )
        except completion_record.CompletionRecordError as exc:
            out(f"오류: 완료 기록을 쓰지 않았습니다 — {exc}")
            return EXIT_USAGE
        except (OSError, ValueError) as exc:
            out(f"오류: 완료 기록 쓰기 실패 ({type(exc).__name__}: {exc})")
